import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const f=JSON.parse('{"title":"Chainy offline records and teacher collection","description":"Owners: Christian (storage), Sean (research records), Sherwin (site coordination), Miguel (screens). October 12, 2026.","frontmatter":{"title":"Chainy offline records and teacher collection","description":"Owners: Christian (storage), Sean (research records), Sherwin (site coordination), Miguel (screens). October 12, 2026.","source":"docs/offline-data-plan.md","category":"Research & evaluation","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/offline-data-plan.md","filePath":"content/docs/offline-data-plan.md"}'),i={name:"content/docs/offline-data-plan.md"};function n(s,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-offline-records-and-teacher-collection">Chainy offline records and teacher collection<a class="header-anchor" href="#chainy-offline-records-and-teacher-collection" aria-label="Link to this section">​</a></h1><p>Owners: Christian (storage), Sean (research records), Sherwin (site coordination), Miguel (screens). October 12, 2026.</p><h2 id="four-separate-jobs">Four separate jobs<a class="header-anchor" href="#four-separate-jobs" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Job</th><th>What it means</th></tr></thead><tbody><tr><td>Play and save</td><td>The game reads/writes local SQLite without internet</td></tr><tr><td>Collect records</td><td>A teacher exports the approved data from each device</td></tr><tr><td>Transfer a file</td><td>Staff carry or send that export to the agreed restricted destination</td></tr><tr><td>Update the app</td><td>Staff install the approved build using a tested update procedure</td></tr></tbody></table><p>SQLite does not automatically upload records. A learner code entered on another device does not restore progress. A local isTeacher flag is not verified staff authentication.</p><h2 id="keep-the-first-collection-workflow-small">Keep the first collection workflow small<a class="header-anchor" href="#keep-the-first-collection-workflow-small" aria-label="Link to this section">​</a></h2><p>Sean defines which records answer the approved study questions. Christian then supplies a consistent export of those fields. Staff verify that the file is readable and belongs to the expected build/content version before ending collection.</p><p>Recommend a simple staff-operated export and review process, without a new teacher web dashboard or backend. Choose CSV or JSON after the record structure is known; no format or importer framework is prescribed by this revision.</p><p>Each exported result needs enough identity to detect repeated collection without counting it twice. Christian and Sean must agree whether the required unit is a current lesson summary, a completed playthrough or individual answers. The source&#39;s current progress/analytics fields do not establish historical attempt storage.</p><h2 id="data-handling">Data handling<a class="header-anchor" href="#data-handling" aria-label="Link to this section">​</a></h2><p>Use learner codes for collection; keep any identity mapping with the authorized teacher. Confirm whether username and age are needed before exposing them in research exports. Participant records, photos with identities, credentials and signing keys stay out of GitHub and public documentation.</p><p>Sean records the custodian, approved destination, permission process, retention and deletion rules. Fixed beta dates do not replace those arrangements.</p><h2 id="failure-and-recovery">Failure and recovery<a class="header-anchor" href="#failure-and-recovery" aria-label="Link to this section">​</a></h2><ul><li>Canceling or failing an export leaves local records intact.</li><li>A successful file write is separate from confirmation that staff received usable records.</li><li>Repeated exports/imports must not inflate the study totals.</li><li>Switching profiles must never mix two learners&#39; records.</li><li>Test app updates with synthetic records before using them on study devices.</li><li>Preserve a recoverable copy before any database change; do not copy a live SQLite file casually.</li><li>Do not delete local records merely because export was attempted.</li></ul><p>CH-04 verifies local records; CH-11 implements the agreed collection method; CH-12 approves the evidence procedure; CH-14 checks the complete workflow. See <a href="/Chainy-Docs/content/docs/design/database-schema.html">database questions</a> and <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation</a>.</p></div>',1)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
